// Title: How to set a custom HTML page title when saving a workbook with Aspose.Cells for .NET (C#)
// Common Searches: C# Aspose.Cells set HTML page title when saving workbook | How to add <title> tag to HTML output generated by Aspose.Cells | Aspose.Cells HtmlSaveOptions title property missing workaround | Save Excel workbook as HTML with custom title using Aspose.Cells .NET | Add custom page title to HTML file after Aspose.Cells export in C#
// Tags: Aspose.Cells HtmlSaveOptions custom title | C# export workbook to HTML with page title | Aspose.Cells HTML title tag workaround | set title element in Aspose.Cells HTML output | Aspose.Cells .NET HTML export title property

using System;
using System.IO;
using Aspose.Cells;

// The example creates a workbook, writes sample data, configures HtmlSaveOptions for HTML output (noting that the HtmlTitle property is unavailable in this version), ensures the output directory exists, saves the workbook as "output.html", and suggests adding a custom <title> tag manually after export.
class Program
{
    static void Main()
    {
        try
        {
            // Create a new workbook and add sample data
            Workbook workbook = new Workbook();
            Worksheet sheet = workbook.Worksheets[0];
            sheet.Cells["A1"].PutValue("Hello");
            sheet.Cells["B1"].PutValue("World");

            // Configure HTML save options (Title property is not available in this version)
            HtmlSaveOptions htmlOptions = new HtmlSaveOptions(SaveFormat.Html);
            // If a title is required, it can be added manually after saving the HTML file.

            // Define output file path
            string outputPath = "output.html";

            // Ensure the output directory exists
            string outputDir = Path.GetDirectoryName(Path.GetFullPath(outputPath));
            if (!string.IsNullOrEmpty(outputDir) && !Directory.Exists(outputDir))
            {
                Directory.CreateDirectory(outputDir);
            }

            // Save the workbook as an HTML file using the specified options
            workbook.Save(outputPath, htmlOptions);
            Console.WriteLine($"Workbook successfully saved to '{outputPath}'.");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }
}
